<?php

declare(strict_types = 1);

namespace Optional\Tests;

/**
 * Finds the ```php examples in src/ and README.md.
 *
 * Shared by the three things that need them: the suite that executes them, the
 * generator that writes them out for psalm, and the test that checks the
 * generated file is current.
 */
final class ExampleSource {
   public const SOURCE_FILES = [
      'src/Option.php',
      'src/Result.php',
      'src/Exceptions/MissingValueException.php',
      'README.md',
   ];

   public const PRELUDE = <<<'PHP'
      use Optional\Option;
      use Optional\Result;
      PHP;

   /**
    * @return list<array{file: string, index: int, symbol: string, code: string}>
    */
   public static function all(): array {
      $root = dirname(__DIR__);
      $examples = [];

      foreach (self::SOURCE_FILES as $relativePath) {
         $source = (string) file_get_contents("{$root}/{$relativePath}");

         foreach (self::extract($source) as $index => $example) {
            $examples[] = [
               'file' => $relativePath,
               'index' => $index + 1,
               'symbol' => $example['symbol'],
               'code' => $example['code'],
            ];
         }
      }

      return $examples;
   }

   /**
    * Renders every example as its own function, so one example's variables
    * cannot reach another's and psalm checks each in isolation.
    */
   public static function render(): string {
      $out = "<?php\n\n"
         . "// Generated by bin/generate-example-checks.php. Do not edit.\n"
         . "// Every ```php example in src/ and README.md, so psalm analyses them.\n\n"
         . "// No namespace on purpose. eval() resolves a bare class name in the\n"
         . "// global namespace, so that is the context the examples really run in.\n\n"
         . "declare(strict_types = 1);\n\n"
         . str_replace('      ', '', self::PRELUDE) . "\n\n";

      foreach (self::all() as $position => $example) {
         $name = 'example' . ($position + 1) . '_' . (string) preg_replace('/\W+/', '_', $example['symbol']);
         $out .= sprintf(
            "/**\n * %s #%d, %s()\n */\nfunction %s(): void {\n%s\n}\n\n",
            $example['file'],
            $example['index'],
            $example['symbol'],
            $name,
            self::indent($example['code'])
         );
      }

      return $out;
   }

   /**
    * Runs one example with PRELUDE's imports and returns what it printed
    *
    * Several examples call error_log(), which goes to stderr in CLI and slips
    * past output buffering, so the error log points at a temp file meanwhile.
    * A throw from the example propagates.
    */
   public static function run(string $code): string {
      $previousLog = ini_get('error_log');
      $sink = tempnam(sys_get_temp_dir(), 'docblock-example-');

      if ($sink !== false) {
         ini_set('error_log', $sink);
      }

      ob_start();

      try {
         self::evaluate($code);
      } finally {
         $printed = (string) ob_get_clean();
         ini_set('error_log', $previousLog === false ? '' : $previousLog);

         if ($sink !== false) {
            unlink($sink);
         }
      }

      return $printed;
   }

   /**
    * @psalm-suppress ForbiddenCode running the examples is the entire point
    */
   private static function evaluate(string $code): void {
      eval(self::PRELUDE . "\n" . $code);
   }

   /**
    * What an example says it prints, from the comment after each `echo`
    *
    * `// "text"` states the line inside the quotes; anything after the closing
    * quote is commentary. `// text` states everything up to the first ", "
    * outside brackets, so `// Some(3), after the retry` states `Some(3)`. An
    * echo with no comment is null: it is not checked, but it still prints a
    * line, so the ones after it stay in step.
    *
    * @return list<string|null>
    */
   public static function statedOutput(string $code): array {
      $stated = [];
      $inEcho = false;

      foreach (explode("\n", $code) as $line) {
         if (str_starts_with(ltrim($line), 'echo ')) {
            $inEcho = true;
         }

         if ($inEcho && preg_match('~;\s*(?://(.*))?$~', $line, $match) === 1) {
            $stated[] = isset($match[1]) ? self::statement(trim($match[1])) : null;
            $inEcho = false;
         }
      }

      return $stated;
   }

   private static function statement(string $comment): string {
      if (str_starts_with($comment, '"')) {
         $close = strpos($comment, '"', 1);

         return substr($comment, 1, $close === false ? null : $close - 1);
      }

      $depth = 0;

      for ($i = 0, $length = strlen($comment); $i < $length; $i++) {
         $depth += match ($comment[$i]) {
            '(', '[' => 1,
            ')', ']' => -1,
            default => 0,
         };

         if ($depth === 0 && substr($comment, $i, 2) === ', ') {
            return substr($comment, 0, $i);
         }
      }

      return $comment;
   }

   /**
    * @return list<array{symbol: string, code: string}>
    */
   private static function extract(string $source): array {
      $examples = [];
      $offset = 0;
      $open = "```php\n";

      while (($start = strpos($source, $open, $offset)) !== false) {
         $bodyAt = $start + strlen($open);
         $end = strpos($source, '```', $bodyAt);

         if ($end === false) {
            break;
         }

         $code = trim(implode("\n", array_map(
            static fn(string $line): string => (string) preg_replace('/^\s*\*\s?/', '', $line),
            explode("\n", substr($source, $bodyAt, $end - $bodyAt))
         )));

         if ($code !== '') {
            $examples[] = ['symbol' => self::symbolAfter($source, $end), 'code' => $code];
         }

         $offset = $end + 3;
      }

      return $examples;
   }

   private static function symbolAfter(string $source, int $offset): string {
      $tail = substr($source, $offset, 4000);

      return preg_match('/public\s+(?:static\s+)?function\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(/', $tail, $m) === 1 ? $m[1] : 'unknown';
   }

   private static function indent(string $code): string {
      return implode("\n", array_map(
         static fn(string $line): string => $line === '' ? '' : '   ' . $line,
         explode("\n", $code)
      ));
   }
}
